/* ============================================================
   «Квартирный вопрос: Суздаль» — игровая логика.
   Данные (const LISTINGS) подставляются при сборке выше в файле.
   Без сборки и бэкенда: чистый JS, готово к GitHub Pages.
   ============================================================ */
(function () {
  'use strict';

  var $ = function (sel, root) { return (root || document).querySelector(sel); };
  var app = document.getElementById('app');

  /* ---------- Константы игры ---------- */
  var CARDS_PER_ROUND = 10;
  var ROUND_COUNT = Math.max(1, Math.floor(LISTINGS.length / CARDS_PER_ROUND));
  var POOL = LISTINGS.slice(0, ROUND_COUNT * CARDS_PER_ROUND);
  var MAX_ROUND = CARDS_PER_ROUND * 10;

  var prices = POOL.map(function (l) { return l.price; });
  var P_MIN = Math.floor(Math.min.apply(null, prices) * 0.85 / 50) * 50;
  var P_MAX = Math.ceil(Math.max.apply(null, prices) * 1.12 / 50) * 50;
  var STEP = 50;
  var DEFAULT_GUESS = Math.round((P_MIN + P_MAX) / 2 / 50) * 50;

  /* ---------- Состояние ---------- */
  var S = {
    screen: 'start',   // start | game | round | final
    reveal: false,
    rounds: [],
    ri: 0, ci: 0, gi: 0,
    total: 0, roundPts: 0,
    results: [],
    usedJokes: {},
    lastReveal: null
  };

  /* ---------- Утилиты ---------- */
  function fmt(n) {
    n = Math.round(n);
    var s = String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\u00a0');
    return (n < 0 ? '−' : '') + s + ' ₽';
  }
  function shuffle(a) {
    a = a.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }
  function median(a) {
    var s = a.slice().sort(function (x, y) { return x - y; });
    var m = s.length >> 1;
    return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
  }
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }
  function bestScore() {
    try { return Number(localStorage.getItem('kvs_best') || 0); } catch (e) { return 0; }
  }
  function saveScore(total) {
    try {
      if (total > bestScore()) localStorage.setItem('kvs_best', String(total));
    } catch (e) { /* приватный режим — не беда */ }
  }

  /* ---------- Раздача: перемешать, отсортировать по цене, раздать по кругу ---------- */
  function deal() {
    var deck = shuffle(POOL).sort(function (a, b) { return a.price - b.price; });
    var rounds = [];
    for (var r = 0; r < ROUND_COUNT; r++) rounds.push([]);
    for (var i = 0; i < deck.length; i++) rounds[i % ROUND_COUNT].push(deck[i]);
    rounds = shuffle(rounds);
    for (var k = 0; k < rounds.length; k++) rounds[k] = shuffle(rounds[k]);
    return rounds;
  }

  /* ---------- Баллы ---------- */
  function pointsFor(relPct) {
    if (relPct <= 5) return 10;
    if (relPct <= 15) return 7;
    if (relPct <= 30) return 4;
    if (relPct <= 50) return 2;
    return 0;
  }
  var PTS_LABEL = { 10: '+10 · снайпер', 7: '+7 · близко', 4: '+4 · тепло', 2: '+2 · мимо', 0: '0 · холодно' };

  /* ---------- Шутки (самоирония миллениала) ---------- */
  var JOKE_BADGE = {
    'Суперхозяин': 'Суперхозяин — это как супергерой, только сдаёт квартиру и не спасает мир.',
    'Мгновенная бронь': 'Мгновенная бронь: потому что решать — это для взрослых.',
    'Без залога': 'Без залога — потому что залог доверия уже потерян.'
  };
  var JOKE_POOL = [
    'В описании «уютно» — читай «маленько, но с душой и Wi-Fi».',
    'Цена за сутки. За сутки твоей жизни. Подумай об этом.',
    'Суперхозяин значит, что хозяин супер, а ты — просто гость.',
    'Это не отель, это «как дома» — только посуда чужая.',
    '1-к. квартира 30 м² — идеально для интроверта с ноутбуком.',
    'Курение запрещено, вечеринки запрещены, веселье — по согласованию.',
    'Депозит возвращается после проверки. Как и твоя вера в людей.',
    'До центра 15 минут пешком — это 15 минут, чтобы передумать.'
  ];
  var JOKE_ZERO = 'Это не баг, это фича. Твоя оценка — тоже.';
  var JOKE_OVERPAY = 'Платить {p} за ночь в Суздале — это инвестиция в воспоминания (и в чужой ремонт).';
  var JOKE_FINAL_NONE = 'Суздаль тебя запомнил. И твою точность тоже.';

  function pickJoke(item, pts, overpaidBig) {
    var badges = item.badges || [];
    for (var i = 0; i < badges.length; i++) {
      var b = badges[i];
      if (JOKE_BADGE[b] && !S.usedJokes[b]) {
        S.usedJokes[b] = 1;
        return JOKE_BADGE[b];
      }
    }
    if (pts === 0) return JOKE_ZERO;
    if (overpaidBig) return JOKE_OVERPAY.replace('{p}', fmt(item.price));
    var pool = JOKE_POOL.filter(function (j) { return !S.usedJokes[j]; });
    if (!pool.length) {
      S.usedJokes = {};
      pool = JOKE_POOL.slice();
    }
    var j = pool[Math.floor(Math.random() * pool.length)];
    S.usedJokes[j] = 1;
    return j;
  }

  /* ---------- Рендер: шапка ---------- */
  function headerHTML() {
    var segs = '';
    for (var i = 0; i < ROUND_COUNT; i++) {
      var done = i < S.ri || (S.screen === 'round' && i === S.ri);
      var cur = S.screen !== 'round' && i === S.ri;
      segs += '<div class="seg' + (done ? ' done' : cur ? ' cur' : '') + '"></div>';
    }
    var left;
    if (S.screen === 'round') {
      left = 'Раунд ' + (S.ri + 1) + ' из ' + ROUND_COUNT + ' завершён';
    } else {
      left = 'Раунд ' + (S.ri + 1) + ' из ' + ROUND_COUNT + ' · карточка ' + (S.ci + 1) + '/' + CARDS_PER_ROUND;
    }
    return '<header class="hdr"><div class="hdr-row"><span>' + left + '</span>' +
      '<span class="score">Баллы: ' + S.total + '</span></div>' +
      '<div class="round-seg">' + segs + '</div></header>';
  }

  /* ---------- Рендер: галерея ---------- */
  function galleryHTML(item) {
    var imgs = '';
    for (var i = 0; i < item.images.length; i++) {
      var eager = (S.ri === 0 && S.ci === 0 && i === 0);
      imgs += '<img src="' + esc(item.images[i]) + '"' +
        (eager ? ' loading="eager" fetchpriority="high"' : ' loading="lazy"') +
        ' decoding="async" width="800" height="533" referrerpolicy="no-referrer" alt="Фото ' + (i + 1) + ' — ' + esc(item.title) + '">';
    }
    var dots = '';
    for (var d = 0; d < item.images.length; d++) dots += '<span class="dot' + (d === 0 ? ' on' : '') + '"></span>';
    return '<div class="gal" id="gal">' +
      '<div class="gal-track" id="gtrack">' + imgs + '</div>' +
      (item.images.length > 1
        ? '<button class="gnav prev" id="gprev" aria-label="Предыдущее фото">‹</button>' +
          '<button class="gnav next" id="gnext" aria-label="Следующее фото">›</button>' +
          '<div class="dots" id="gdots">' + dots + '</div>' +
          '<div class="ph-count" id="gcount">1/' + item.images.length + '</div>'
        : '') +
      '</div>';
  }

  function gShow(idx) {
    var item = S.rounds[S.ri][S.ci];
    var n = item.images.length;
    S.gi = (idx + n) % n;
    var track = $('#gtrack');
    if (track) track.style.transform = 'translateX(-' + (S.gi * 100) + '%)';
    var dots = document.querySelectorAll('#gdots .dot');
    for (var i = 0; i < dots.length; i++) dots[i].className = 'dot' + (i === S.gi ? ' on' : '');
    var cnt = $('#gcount');
    if (cnt) cnt.textContent = (S.gi + 1) + '/' + n;
  }
  function gNext() { gShow(S.gi + 1); }
  function gPrev() { gShow(S.gi - 1); }

  function bindGallery(item) {
    var gal = $('#gal');
    if (!gal) return;
    var prev = $('#gprev'), next = $('#gnext');
    if (prev) prev.addEventListener('click', gPrev);
    if (next) next.addEventListener('click', gNext);
    var tx0 = null;
    gal.addEventListener('touchstart', function (e) { tx0 = e.touches[0].clientX; }, { passive: true });
    gal.addEventListener('touchend', function (e) {
      if (tx0 === null) return;
      var dx = e.changedTouches[0].clientX - tx0;
      if (Math.abs(dx) > 40) { if (dx < 0) gNext(); else gPrev(); }
      tx0 = null;
    }, { passive: true });
  }

  /* ---------- Рендер: инфо о жилье ---------- */
  function infoHTML(item) {
    var chips = '';
    if (item.area) chips += '<span class="chip">' + esc(item.area) + '</span>';
    if (item.cap) chips += '<span class="chip">' + esc(item.cap) + '</span>';
    if (item.amen && item.amen.length) chips += '<span class="chip">' + esc(item.amen.join(' · ')) + '</span>';
    (item.badges || []).forEach(function (b) { chips += '<span class="chip bdg">' + esc(b) + '</span>'; });
    return '<div class="card-info">' +
      '<h2 class="t">' + esc(item.title) + '</h2>' +
      '<div class="addr"><svg width="11" height="13" viewBox="0 0 11 13" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5.5 0C2.6 0 .3 2.3.3 5.2c0 3.9 5.2 7.6 5.2 7.6s5.2-3.7 5.2-7.6C10.7 2.3 8.4 0 5.5 0zm0 7.2a2 2 0 1 1 0-4 2 2 0 0 1 0 4z" fill="#165DAA"/></svg><span>' + esc(item.address) + '</span></div>' +
      (chips ? '<div class="chips">' + chips + '</div>' : '') +
      (item.desc ? '<p class="desc">' + esc(item.desc) + '</p>' : '') +
      '</div>';
  }

  /* ---------- Рендер: слайдер ---------- */
  function posCSS(price) {
    var p = (price - P_MIN) / (P_MAX - P_MIN) * 100;
    p = Math.max(0, Math.min(100, p));
    return 'calc(14px + (100% - 28px) * ' + (p / 100) + ')';
  }
  function sliderHTML(value) {
    return '<div class="guess" id="guessArea">' +
      '<div class="guess-row"><span class="lbl">Твоя цена за ночь</span><span class="val" id="gval">' + fmt(value) + '</span></div>' +
      '<div class="slider">' +
      '<div class="track"><div class="fill" id="gfill"></div></div>' +
      '<div class="thumb" id="gthumb"></div>' +
      '<input type="range" id="range" min="' + P_MIN + '" max="' + P_MAX + '" step="' + STEP + '" value="' + value + '" aria-label="Оценка цены за ночь, рублей">' +
      '</div>' +
      '<div class="range-ends"><span>' + fmt(P_MIN) + '</span><span>' + fmt(P_MAX) + '</span></div>' +
      '<button data-primary class="btn" id="rate">Оценить</button>' +
      '</div>';
  }
  function syncSlider(value) {
    var p = (value - P_MIN) / (P_MAX - P_MIN) * 100;
    p = Math.max(0, Math.min(100, p));
    var fill = $('#gfill'), thumb = $('#gthumb'), val = $('#gval');
    if (val) val.textContent = fmt(value);
    if (fill) fill.style.width = p + '%';
    if (thumb) thumb.style.left = posCSS(value);
  }

  /* ---------- Экран игры ---------- */
  function renderGame() {
    var item = S.rounds[S.ri][S.ci];
    S.gi = 0;
    S.screen = 'game';
    app.innerHTML = headerHTML() +
      '<div class="screen">' +
      galleryHTML(item) +
      '<div class="body">' + infoHTML(item) + sliderHTML(DEFAULT_GUESS) + '</div>' +
      '</div>';
    bindGallery(item);
    syncSlider(DEFAULT_GUESS);
    $('#range').addEventListener('input', function () {
      syncSlider(Number(this.value));
    });
    $('#rate').addEventListener('click', rate);
  }

  function rate() {
    var item = S.rounds[S.ri][S.ci];
    var guess = Number($('#range').value);
    var real = item.price;
    var d = guess - real;
    var rel = Math.abs(d) / real * 100;
    var pts = pointsFor(rel);
    S.total += pts;
    S.roundPts += pts;
    S.results.push({ id: item.id, g: guess, real: real, d: d, rel: rel, pts: pts });
    S.reveal = true;
    S.lastReveal = {
      guess: guess, real: real, d: d, rel: rel, pts: pts,
      joke: pickJoke(item, pts, d > real * 0.3)
    };
    renderReveal();
  }

  function renderReveal() {
    var r = S.lastReveal;
    var item = S.rounds[S.ri][S.ci];
    var diffCls, diffTxt;
    if (r.d === 0) {
      diffCls = 'ok';
      diffTxt = 'В точку! Ты назвал цену ровно.';
    } else if (r.d > 0) {
      diffCls = 'up';
      diffTxt = 'Ты оценил дороже на +' + fmt(r.d) + ' (' + Math.round(r.rel) + '%)';
    } else {
      diffCls = 'down';
      diffTxt = 'Ты оценил дешевле на ' + fmt(r.d) + ' (' + Math.round(r.rel) + '%)';
    }
    var isLast = S.ci === CARDS_PER_ROUND - 1;
    $('#guessArea').outerHTML =
      '<div class="reveal">' +
      '<div class="rv-top"><div><div class="rv-lbl">Реальная цена</div><div class="rv-price">' + fmt(r.real) + '</div></div>' +
      '<div class="pts-badge p' + r.pts + '">' + PTS_LABEL[r.pts] + '</div></div>' +
      '<div class="rv-diff ' + diffCls + '">' + diffTxt + '</div>' +
      '<div class="joke">«' + esc(r.joke) + '»</div>' +
      '<a class="alink" href="' + esc(item.href) + '" target="_blank" rel="noopener">Смотреть объявление на Авито →</a>' +
      '<button data-primary class="btn" id="nextBtn">' + (isLast ? 'Итоги раунда' : 'Дальше') + '</button>' +
      '</div>';
    $('#nextBtn').addEventListener('click', next);
  }

  function next() {
    if (S.ci < CARDS_PER_ROUND - 1) {
      S.ci++;
      renderGame();
    } else {
      renderRoundSummary();
    }
  }

  /* ---------- Экран: итоги раунда ---------- */
  var DOT_COLORS = { 10: 'var(--good)', 7: 'var(--lime)', 4: '#DBA73C', 2: '#D07C2E', 0: 'var(--bad)' };
  function renderRoundSummary() {
    S.screen = 'round';
    var roundResults = S.results.slice(-CARDS_PER_ROUND);
    var best = roundResults.reduce(function (a, b) { return b.rel < a.rel ? b : a; }, roundResults[0]);
    var bestItem = null;
    for (var i = 0; i < S.rounds[S.ri].length; i++) {
      if (S.rounds[S.ri][i].id === best.id) bestItem = S.rounds[S.ri][i];
    }
    var dots = '';
    roundResults.forEach(function (r) { dots += '<i style="background:' + DOT_COLORS[r.pts] + '" title="' + r.pts + ' баллов"></i>'; });
    var isLast = S.ri === ROUND_COUNT - 1;
    app.innerHTML = headerHTML() +
      '<div class="screen roundsum">' +
      '<div class="eyebrow">Раунд ' + (S.ri + 1) + ' из ' + ROUND_COUNT + '</div>' +
      '<div class="rs-score">' + S.roundPts + '<span> / ' + MAX_ROUND + '</span></div>' +
      '<div class="rs-bar"><i style="width:' + Math.round(S.roundPts / MAX_ROUND * 100) + '%"></i></div>' +
      '<div class="rs-dots">' + dots + '</div>' +
      (bestItem
        ? '<p class="rs-best">Точнее всего: <b>«' + esc(bestItem.title) + '»</b> — промах ' + Math.round(best.rel) + '%</p>'
        : '') +
      '<p class="rs-total">Всего баллов: ' + S.total + ' из ' + (MAX_ROUND * ROUND_COUNT) + '</p>' +
      '<div class="joke">«' + esc(isLast
        ? 'Финальный свисток. Считаем деньги и самооценку.'
        : 'Передышка. Суздаль ждёт, ипотека тоже.') + '»</div>' +
      '<button data-primary class="btn">' + (isLast ? 'Показать итоги игры' : 'Следующий раунд') + '</button>' +
      '</div>';
    $('[data-primary]').addEventListener('click', nextRound);
  }

  function nextRound() {
    if (S.ri < ROUND_COUNT - 1) {
      S.ri++;
      S.ci = 0;
      S.roundPts = 0;
      renderGame();
    } else {
      renderFinal();
    }
  }

  /* ---------- Экран: финал ---------- */
  function finalVerdict(results) {
    var medRel = median(results.map(function (r) { return (r.g - r.real) / r.real * 100; }));
    if (medRel > 5) {
      return {
        title: 'Транжира',
        sub: 'Ты оценивал жильё щедрее, чем хозяева. Суздаль это одобряет, твой кошелёк — нет.'
      };
    }
    if (medRel < -5) {
      return {
        title: 'Экономный гость',
        sub: 'Ты оценивал дешевле рынка. Хозяева незаметно плачут, а ты — молодец.'
      };
    }
    return {
      title: 'Адекватный квартирант',
      sub: 'Ты чувствуешь цены Суздаля. Риелторы города нервно курят в сторонке.'
    };
  }
  function overpayThing(y) {
    var a = Math.abs(y);
    if (a < 1000) return '3 чашки кофе в Суздале';
    if (a < 2500) return 'билет в аквапарк';
    if (a < 6000) return 'дегустацию медовухи и магнитик с медведем';
    if (a < 15000) return 'баню на дровах целиком, с веником и самоваром';
    return 'мини-тур по Золотому кольцу с остановкой на медовуху';
  }
  function renderFinal() {
    S.screen = 'final';
    saveScore(S.total);
    var v = finalVerdict(S.results);
    var n = S.results.length;
    var diffs = S.results.map(function (r) { return r.g - r.real; });
    var avg = diffs.reduce(function (a, b) { return a + b; }, 0) / n;
    var avg10 = avg * 10;
    var medRel = median(S.results.map(function (r) { return (r.g - r.real) / r.real * 100; }));
    var exact = S.results.filter(function (r) { return r.rel <= 5; }).length;
    var medSign = medRel > 0 ? '+' : '';
    var thing = overpayThing(avg10);
    var overpayHTML;
    if (avg > 10) {
      overpayHTML = 'Вы переплатили в среднем на <b>' + fmt(avg) + '</b> за ночь. За 10 ночей это <b>' + fmt(avg10) + '</b> — хватило бы на ' + thing + '.';
    } else if (avg < -10) {
      overpayHTML = 'Вы сэкономили в среднем <b>' + fmt(Math.abs(avg)) + '</b> за ночь. За 10 ночей это <b>' + fmt(Math.abs(avg10)) + '</b> — хватило бы на ' + thing + '. Не благодарите.';
    } else {
      overpayHTML = 'Вы вышли в ноль. Подозрительная точность — может, вы местный риелтор?';
    }
    var joke = JOKE_POOL.filter(function (j) { return !S.usedJokes[j]; })[0] || JOKE_FINAL_NONE;
    var segs = '';
    for (var i = 0; i < ROUND_COUNT; i++) segs += '<div class="seg done"></div>';
    var prevBest = bestScore();
    app.innerHTML =
      '<header class="hdr"><div class="hdr-row"><span>Игра завершена</span><span class="score">Баллы: ' + S.total + '</span></div>' +
      '<div class="round-seg">' + segs + '</div></header>' +
      '<div class="screen final">' +
      '<div class="eyebrow">Твой вердикт</div>' +
      '<h1 class="f-title">' + v.title + '</h1>' +
      '<p class="f-sub">' + v.sub + '</p>' +
      '<div class="f-score">' + S.total + '<span> / ' + (MAX_ROUND * ROUND_COUNT) + '</span></div>' +
      '<div class="card f-stats">' +
      '<div class="f-row"><span>Медианный промах</span><b>' + medSign + Math.round(medRel) + '%</b></div>' +
      '<div class="f-row"><span>Точных попаданий (≤5%)</span><b>' + exact + ' из ' + n + '</b></div>' +
      '<div class="f-row"><span>Средняя оценка против реальности</span><b>' + (avg > 0 ? '+' : '') + fmt(avg) + '/ночь</b></div>' +
      '</div>' +
      '<div class="card f-overpay"><p>' + overpayHTML + '</p></div>' +
      '<div class="joke">«' + esc(joke) + '»</div>' +
      '<button data-primary class="btn">Играть снова</button>' +
      '<div class="meta">Рекорд: ' + Math.max(prevBest, S.total) + ' из ' + (MAX_ROUND * ROUND_COUNT) +
      ' · ' + POOL.length + ' реальных объявлений Суздаля</div>' +
      '</div>';
    $('[data-primary]').addEventListener('click', startGame);
  }

  /* ---------- Стартовый экран ---------- */
  function renderStart() {
    S.screen = 'start';
    var best = bestScore();
    var bestHTML = best > 0 ? ' · твой рекорд: ' + best + ' из ' + (MAX_ROUND * ROUND_COUNT) : '';
    app.innerHTML =
      '<div class="screen start">' +
      '<div class="eyebrow">Игра по реальным объявлениям Авито</div>' +
      '<h1>Квартирный вопрос:<br>Суздаль</h1>' +
      '<p class="slogan">«Угадай цену — почувствуй себя риелтором, который всё ещё платит ипотеку»</p>' +
      '<div class="card rules"><div class="rules-title">Как играть</div><ol>' +
      '<li>Смотри фото и факты — и двигай бегунок: сколько стоит ночь?</li>' +
      '<li>Жмёшь «Оценить» — видишь реальную цену, свой промах и баллы.</li>' +
      '<li>' + ROUND_COUNT + ' раунда по ' + CARDS_PER_ROUND + ' карточек. В финале — вердикт: транжира, экономный гость или адекватный квартирант.</li>' +
      '</ol></div>' +
      '<div class="card"><div class="rules-title">Баллы за промах</div><div class="sct">' +
      '<span class="chip">≤5% → 10</span><span class="chip">≤15% → 7</span><span class="chip">≤30% → 4</span>' +
      '<span class="chip">≤50% → 2</span><span class="chip">&gt;50% → 0</span></div>' +
      '<p class="meta" style="text-align:left;margin-top:9px">Максимум за раунд — ' + MAX_ROUND + ' баллов. Всего — ' + (MAX_ROUND * ROUND_COUNT) + '.</p></div>' +
      '<div class="meta">' + POOL.length + ' реальных объявлений · цены за ночь для 2 гостей · ноябрь 2026' + bestHTML + '</div>' +
      '<div class="foot">Это не баг, это фича.</div>' +
      '<button data-primary class="btn">Запуск игры</button>' +
      '</div>';
    $('[data-primary]').addEventListener('click', startGame);
  }

  function startGame() {
    S.rounds = deal();
    S.ri = 0; S.ci = 0;
    S.total = 0; S.roundPts = 0;
    S.results = [];
    S.usedJokes = {};
    S.lastReveal = null;
    S.reveal = false;
    renderGame();
  }

  /* ---------- Клавиатура (для десктопа) ---------- */
  document.addEventListener('keydown', function (e) {
    if (S.screen !== 'game') return;
    if (e.key === 'ArrowLeft') gPrev();
    if (e.key === 'ArrowRight') gNext();
  });

  /* ---------- Хук для автотестов ---------- */
  window.__kvs = {
    state: S,
    g: function (v) {
      var r = $('#range');
      if (!r) return;
      r.value = v;
      r.dispatchEvent(new Event('input', { bubbles: true }));
    },
    p: function () {
      var b = $('[data-primary]');
      if (b) b.click();
    }
  };

  renderStart();
})();
